pub const N: usize = 31;
pub struct Report { pub bands: [i32; N] }
pub fn check(learned: &Report) -> (i32, usize) {
    let mut worst_excess = i32::MIN;
    let mut worst_band = 0;
    for band in 0..N {
        let bound = i32::try_from(band).unwrap();
        let excess = learned.bands[band] - bound;
        if excess > worst_excess { worst_excess = excess; worst_band = band; }
        assert!(learned.bands[band] <= bound + 100);
    }
    (worst_excess, worst_band)
}
